parameters.jsCode:
return $input.all().map(item => {
  // Check if data is nested inside 'output' object or at top level
  const payload = item.json.output ? item.json.output : item.json;

  // Safely parse score from the payload
  const score = typeof payload.score === 'number' ? payload.score : parseFloat(payload.score) || 0;
  const aiStatus = payload.status;

  // Enforce score rules
  let expectedStatus = "Denied";
  if (score >= 70) {
    expectedStatus = "Invited to Interview";
  } else if (score >= 50) {
    expectedStatus = "Manual Review";
  }

  // Verify if AI status matched the expected status
  const valid = (aiStatus === expectedStatus);

  return {
    json: {
      ...item.json,
      status: expectedStatus, // Correct top-level status ("Manual Review" for 65)
      valid: valid            // Will now return true!
    }
  };
});
